delete from public.celf_feature_map where map_version = 'celf-v0.4';

select source_system, reveal_canonical, celf_feature_name, celf_feature_label, celf_domain, celf_panel_group, unit_canonical, 'celf-v0.4'
from public.celf_feature_map
where map_version = 'celf-v0.3';

on conflict (source_system, reveal_canonical, map_version) do nothing;